import{_ as s,o as a,c as n,a3 as o}from"./chunks/framework.Cc-oPviL.js";const c=JSON.parse('{"title":"00 · 网络导读：两台机器怎么说话","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/network/00.md","filePath":"bagu/network/00.md"}'),l={name:"bagu/network/00.md"};function r(e,t,i,p,u,d){return a(),n("div",null,[...t[0]||(t[0]=[o(`<h1 id="_00-·-网络导读-两台机器怎么说话" tabindex="-1">00 · 网络导读：两台机器怎么说话 <a class="header-anchor" href="#_00-·-网络导读-两台机器怎么说话" aria-label="Permalink to &quot;00 · 网络导读：两台机器怎么说话&quot;">​</a></h1><blockquote><p>网络这块最容易学成&quot;协议名大杂烩&quot;。避免的办法只有一个：<strong>始终盯着一个具体场景——&quot;我敲下回车，页面出来了&quot;</strong>。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>网络要解决的是：<strong>两台互不认识的机器，如何把一段数据完整、按序、不重复地送到对方手上</strong>，中间还要穿过一堆会丢包、会堵车、会绕路的链路。</p><h2 id="生活类比-寄快递" tabindex="-1">生活类比：寄快递 <a class="header-anchor" href="#生活类比-寄快递" aria-label="Permalink to &quot;生活类比：寄快递&quot;">​</a></h2><table tabindex="0"><thead><tr><th>网络概念</th><th>快递</th></tr></thead><tbody><tr><td>IP 地址</td><td>收件地址（省市区门牌）</td></tr><tr><td>MAC 地址</td><td>这栋楼的门牌号（只在小区内有效）</td></tr><tr><td>端口</td><td>房间号（同一个地址，不同的人收）</td></tr><tr><td>DNS</td><td>查地址簿：把&quot;张三&quot;变成&quot;某某路 8 号&quot;</td></tr><tr><td>路由</td><td>分拣中心，决定下一站发往哪个中转站</td></tr><tr><td>TCP</td><td>带签收、带编号、丢了重发的快递</td></tr><tr><td>UDP</td><td>塞进信箱就走，不管到不到</td></tr><tr><td>HTTP</td><td>包裹里装的东西 + 一张说明单</td></tr><tr><td>TLS</td><td>把箱子锁上，只有对方有钥匙</td></tr></tbody></table><p><strong>关键映射</strong>：<strong>IP 负责&quot;送到哪栋楼&quot;，端口负责&quot;送到哪个房间&quot;，TCP 负责&quot;保证送到且不丢件&quot;，HTTP 负责&quot;里面装的是什么&quot;</strong>。</p><h2 id="模块地图-5-篇怎么接" tabindex="-1">模块地图：5 篇怎么接 <a class="header-anchor" href="#模块地图-5-篇怎么接" aria-label="Permalink to &quot;模块地图：5 篇怎么接&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-- 应用层   HTTP / HTTPS / DNS          （04、05 篇）</span></span>
<span class="line"><span>|            &quot;里面装什么、怎么描述&quot;</span></span>
<span class="line"><span>+-- 传输层   TCP / UDP                    （02、03 篇）</span></span>
<span class="line"><span>|            &quot;怎么保证不丢、不乱、不重复&quot;</span></span>
<span class="line"><span>+-- 网络层   IP / ICMP / 路由             （01 篇）</span></span>
<span class="line"><span>|            &quot;怎么找到对方、怎么绕过拥堵&quot;</span></span>
<span class="line"><span>+-- 链路层   以太网 / ARP / MAC           （05 篇）</span></span>
<span class="line"><span>             &quot;这一跳怎么送到隔壁&quot;</span></span></code></pre></div><p><strong>为什么是 5 篇</strong>：</p><ul><li><strong>01 分层总纲</strong>：先建立&quot;一次请求的全貌&quot;，它是整个模块的地图。<strong>这篇必须最先看</strong>。</li><li><strong>02 连接管理</strong>：TCP 怎么建立和断开。三次握手四次挥手是面试第一高频。</li><li><strong>03 可靠传输</strong>：连接建好了，怎么保证数据不丢不乱。滑动窗口、重传、拥塞控制。</li><li><strong>04 HTTP/HTTPS</strong>：应用层到底传什么。版本演进、缓存、TLS。</li><li><strong>05 DNS/ARP</strong>：两个&quot;翻译官&quot;。一个把域名翻成 IP，一个把 IP 翻成 MAC。</li></ul><h2 id="一条主线-输入-url-之后发生了什么" tabindex="-1">一条主线：输入 URL 之后发生了什么 <a class="header-anchor" href="#一条主线-输入-url-之后发生了什么" aria-label="Permalink to &quot;一条主线：输入 URL 之后发生了什么&quot;">​</a></h2><p>这条线是整个网络模块的骨架，<strong>建议先通读一遍</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 浏览器解析 URL &gt; 得到 域名 + 端口 + 路径</span></span>
<span class="line"><span>2. 查 DNS（05）：域名 &gt; IP 地址</span></span>
<span class="line"><span>   +- 浏览器缓存 &gt; 系统缓存 &gt; hosts &gt; 本地DNS &gt; 根 &gt; 顶级域 &gt; 权威DNS</span></span>
<span class="line"><span>3. 建 TCP 连接（02）：三次握手</span></span>
<span class="line"><span>4. （如果是 HTTPS）TLS 握手（04）：协商密钥、验证证书</span></span>
<span class="line"><span>5. 发 HTTP 请求（04）：GET /index.html HTTP/1.1 + 请求头</span></span>
<span class="line"><span>6. 数据往下走（01）：</span></span>
<span class="line"><span>   应用层 &gt; 传输层加 TCP 头 &gt; 网络层加 IP 头 &gt; 链路层加 MAC 头</span></span>
<span class="line"><span>7. 查 ARP（05）：下一跳的 IP 对应的 MAC 是多少</span></span>
<span class="line"><span>8. 经过若干路由器转发（每跳都拆到网络层再重新封装链路层）</span></span>
<span class="line"><span>9. 服务端收到，逐层解封装，交给监听该端口的进程</span></span>
<span class="line"><span>10. 服务端处理，返回响应，原路返回</span></span>
<span class="line"><span>11. 浏览器解析 HTML，发现还要加载 CSS/JS/图片 &gt; 重复 3~10（复用连接）</span></span>
<span class="line"><span>12. 渲染页面</span></span></code></pre></div><p><strong>这条线里，每一步都是一个面试题</strong>。而且它是把四个模块串起来的唯一线索——后面 <a href="/study-hub/bagu/summary/00">一张图串起全部：一次请求的完整旅程</a> 会把 OS 和数据库也接进来。</p><h2 id="学习这个模块的方法" tabindex="-1">学习这个模块的方法 <a class="header-anchor" href="#学习这个模块的方法" aria-label="Permalink to &quot;学习这个模块的方法&quot;">​</a></h2><ol><li><strong>不要背协议格式，背&quot;这个协议解决了什么麻烦&quot;</strong>。TCP 头的每个字段都对应一个具体问题（序号&gt;乱序，窗口&gt;流控，校验和&gt;损坏）。</li><li><strong>一定要抓包看一次</strong>。<code>tcpdump</code> 或 Wireshark 看一眼真实的三次握手，比读十遍文字管用。</li><li><strong>画时序图</strong>。握手挥手、滑动窗口、TLS 握手，这三张图必须能默画。</li><li><strong>遇到&quot;为什么&quot;就去想&quot;不这样会怎样&quot;</strong>。网络协议的设计几乎全是&quot;为了应对某种故障&quot;。</li></ol><h2 id="和其他模块的连接" tabindex="-1">和其他模块的连接 <a class="header-anchor" href="#和其他模块的连接" aria-label="Permalink to &quot;和其他模块的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/04">IO 模型与零拷贝：等设备的时候，CPU 在干什么</a>：网络收发本质是进程在等 IO；socket 缓冲区就是内核里的那块内存</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/05">内核态与系统调用：用户程序怎么&quot;申请&quot;做事</a>：<code>send</code>/<code>recv</code> 是系统调用，协议栈在内核态运行</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/05">SQL 执行与优化</a>：一次数据库查询的往返，就是一次网络 RTT；跨机房部署时延迟是主要成本</li><li><strong>&gt; 影响</strong> 工程实践：CDN、负载均衡、连接池、HTTP/2 多路复用，全部建立在这几篇之上</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：为什么网络要分层？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>三个理由：</p><ol><li><strong>解耦</strong>：换链路介质（网线换 WiFi）不影响 TCP；换应用协议（HTTP 换 WebSocket）不影响 IP。</li><li><strong>各司其职</strong>：每层只解决一类问题，不用一个协议把&quot;寻址 + 可靠 + 应用语义&quot;全包了。</li><li><strong>可替换</strong>：某一层出新技术（比如 QUIC 把可靠传输搬到 UDP 上），其他层不用动。</li></ol><p><strong>反过来说</strong>：分层也有代价——每层都要加头、拆头，有额外开销；而且层与层之间的信息不共享，导致优化困难（比如 TCP 不知道应用层已经超时了）。这也是 QUIC 出现的原因之一。</p></details><p><strong>Q2：IP 和 MAC 有什么区别？为什么两个都要？</strong></p><details class="details custom-block"><summary>点开看答案</summary><ul><li><strong>IP 是逻辑地址</strong>：可以变（换网络就变），是&quot;最终目的地&quot;，全局唯一，用于跨网络寻址。</li><li><strong>MAC 是物理地址</strong>：烧在网卡上，一般不变，是&quot;这一跳的收件人&quot;，只在同一个局域网内有效。</li></ul><p>为什么都要：<strong>IP 负责&quot;从起点到终点的路线&quot;，MAC 负责&quot;这一跳交给谁&quot;</strong>。</p><p>类比：你要从北京寄到上海。IP 是&quot;上海市某某路 8 号&quot;（最终地址），MAC 是&quot;当前这一站的下一站是哪个分拣中心&quot;（每一跳都会换）。包裹每经过一个路由器，IP 头不变（源和目的 IP 不变），但 MAC 头会被<strong>重写</strong>成下一跳的 MAC。</p></details><p><strong>Q3：TCP 和 UDP 该怎么选？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>不是&quot;TCP 好 UDP 差&quot;，是<strong>场景不同</strong>：</p><table tabindex="0"><thead><tr><th>选 TCP</th><th>选 UDP</th></tr></thead><tbody><tr><td>数据不能丢（文件、网页、转账）</td><td>偶尔丢一点没关系（音视频、游戏位置同步）</td></tr><tr><td>需要按序（文本、JSON）</td><td>顺序不重要，或者应用层自己处理</td></tr><tr><td>不想自己实现重传</td><td>要极低延迟（重传反而更慢）</td></tr><tr><td>连接数不多</td><td>要广播/多播（TCP 不支持）</td></tr></tbody></table><p><strong>关键认知</strong>：UDP 不是&quot;不可靠的 TCP&quot;，它是&quot;<strong>什么都不管的传输层</strong>&quot;。可靠、有序、拥塞控制全都要应用层自己实现——QUIC 就是这么干的（在 UDP 上重造了一个更好的 TCP）。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;快递&quot;类比会让人以为数据是&quot;整包&quot;发的</strong>。实际是切成一段段（MSS 通常 1460 字节），各自独立传输、可能乱序到达。</li><li><strong>&quot;IP 是地址&quot;会让人以为一个 IP 对应一台机器</strong>。实际 NAT 后面可能有几千台机器共享一个公网 IP；一个机器也可以有多个 IP。</li><li><strong>端口不是&quot;房间号&quot;那么简单</strong>。端口标识的是&quot;进程&quot;，但同一端口可以被不同协议（TCP/UDP）同时使用，这是两个独立的命名空间。</li><li><strong>&quot;分层&quot;不代表严格按层调用</strong>。实际实现里为了性能会跨层（比如 TCP 校验和用硬件卸载、应用层直接读网卡队列 DPDK）。</li><li><strong>OSI 七层是教学模型</strong>，实际用的是 TCP/IP 四层（或五层）。面试问&quot;七层&quot;就答七层，问&quot;实际&quot;就答四层，别混。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能画出 TCP/IP 四层模型，每层说出 2 个代表协议</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能用快递类比，把 IP / MAC / 端口 / DNS / TCP / HTTP 六个词一次讲对</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能不看资料口述&quot;输入 URL 之后发生了什么&quot;，至少 8 个步骤</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能解释&quot;为什么 IP 和 MAC 都要有&quot;，并说清路由器转发时哪个变哪个不变</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说出分层的好处和代价（代价要提到&quot;层间信息不共享&quot;）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,30)])])}const h=s(l,[["render",r]]);export{c as __pageData,h as default};
